// Writes shared/src/generated/schemas.ts: one exported alias per schema, under
// the schema's own name (openapi-typescript's --root-types renames APConfig to
// ApConfig).
import { readFileSync, writeFileSync } from 'node:fs';

const spec = JSON.parse(readFileSync('../../shared/openapi.json', 'utf8'));
const names = Object.keys(spec.components.schemas).sort();
const lines = [
  '// Generated by tools/openapi-gen from shared/openapi.json. Do not edit.',
  "import type { components } from './openapi';",
  '',
  ...names.map((n) => `export type ${n} = components['schemas']['${n}'];`),
  '',
];
writeFileSync('../../shared/src/generated/schemas.ts', lines.join('\n'));
